"""Geant4 optical transport without per-step Python: the cost of Geant4 itself, as in a compiled application.

Same scene, materials and photon energy as g4_sim.py. Differences, all to keep Python out of the photon loop:
  * photons are generated by Geant4's General Particle Source (uniform in a box, isotropic, one call per photon)
    with random linear polarization set by Geant4;
  * photons entering air are absorbed by the air itself (absorption length 1 nm) instead of a Python stepping action;
  * true polarization is tracked (g4_sim.py mode "pol"; its captured fractions equal the averaged-Fresnel mode to
    -0.01 +- 0.26 %);
  * detection: a 1-um slab with the core's refractive index and absorption length 1 nm sits on each readout face; a
    Python sensitive detector is called only for photons that reach it (about 2% of them) and records the emission
    voxel, channel and time.
The only Python per photon is the GPS call in GeneratePrimaries.

usage: python g4_fast.py <gid> <lo x,y,z> <hi x,y,z> <n_photons> <seed> <out.npz>
"""
import sys as _sys, pathlib as _pl  # release: shared modules in ../../code
_sys.path.insert(0, str(_pl.Path(__file__).resolve().parents[1] / "code"))
import paths  # noqa: E402,F401
import math
import os
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
os.environ.setdefault("GEANT4_DATA_DIR", os.path.join(HERE, "g4", "nodata"))
os.makedirs(os.environ["GEANT4_DATA_DIR"], exist_ok=True)
from geant4_pybind import *  # noqa: E402,F403
import json  # noqa: E402

gid = sys.argv[1]
lo = np.array([int(x) for x in sys.argv[2].split(",")])
hi = np.array([int(x) for x in sys.argv[3].split(",")])
NPH, SEED, OUTF = int(sys.argv[4]), int(sys.argv[5]), sys.argv[6]
PER_EVENT = 1000
G = np.load(os.path.join(HERE, "g4", "geom", f"{gid}.npz"))
MATS = json.loads(str(G["materials_json"]))
CELL = G["cell_cm"] * 10.0
SP = CELL / np.array([20, 20, 8])
E_PH = 3.04 * eV
WORLD, SCINT, CLAD0, CORE0, CLAD1, CORE1, PORT0, PORT1 = range(8)
SLAB = 1e-3                                         # mm
m_unit = m


def material(name, density, n, absl_mm):
    mt = G4Material(name, density, 2)
    mt.AddElement(G4NistManager.Instance().FindOrBuildElement("C"), 9)
    mt.AddElement(G4NistManager.Instance().FindOrBuildElement("H"), 10)
    t = G4MaterialPropertiesTable()
    e = [1.5 * eV, 6.2 * eV]
    t.AddProperty("RINDEX", G4doubleVector(e), G4doubleVector([n, n]))
    t.AddProperty("ABSLENGTH", G4doubleVector(e), G4doubleVector([absl_mm, absl_mm]))
    mt.SetMaterialPropertiesTable(t)
    return mt, t


caught = []
emitted = np.zeros(3200, np.int64)


class PortSD(G4VSensitiveDetector):
    def ProcessHits(self, step, hist):
        track = step.GetTrack()
        if track.GetCurrentStepNumber() and step.GetPreStepPoint().GetStepStatus() == G4StepStatus.fGeomBoundary:
            v = track.GetVertexPosition()
            ix = min(int(v.x / SP[0]), 19); iy = min(int(v.y / SP[1]), 19); iz = min(int(v.z / SP[2]), 7)
            k = step.GetPreStepPoint().GetTouchable().GetCopyNumber() - PORT0
            caught.append(((ix * 20 + iy) * 8 + iz, k, step.GetPreStepPoint().GetGlobalTime()))
        track.SetTrackStatus(G4TrackStatus.fStopAndKill)
        return True


class Det(G4VUserDetectorConstruction):
    def Construct(self):
        self.keep = []
        nist = G4NistManager.Instance()
        air = G4Material("abs_air", 1.2e-3 * g / cm3, 1)
        air.AddElement(nist.FindOrBuildElement("N"), 1)
        ta = G4MaterialPropertiesTable()
        ta.AddProperty("RINDEX", G4doubleVector([1.5 * eV, 6.2 * eV]), G4doubleVector([MATS["air"][0]] * 2))
        AIR_ABS = float(os.environ.get("AIR_ABS_MM", "0.01"))
        ta.AddProperty("ABSLENGTH", G4doubleVector([1.5 * eV, 6.2 * eV]), G4doubleVector([AIR_ABS, AIR_ABS]))
        air.SetMaterialPropertiesTable(ta)
        L = lambda mu: (1.0 / mu) * cm if mu > 0 else 1e12
        scm, t1 = material("EJ204", 1.023 * g / cm3, MATS["EJ-204"][0], L(MATS["EJ-204"][1]))
        core, t2 = material("core", 1.05 * g / cm3, MATS["fiber_core"][0], L(MATS["fiber_core"][1]))
        clad, t3 = material("clad", 1.19 * g / cm3, MATS["fiber_clad"][0], L(MATS["fiber_clad"][1]))
        portm, t4 = material("portm", 1.05 * g / cm3, MATS["fiber_core"][0], 1e-6)
        self.keep += [air, ta, scm, t1, core, t2, clad, t3, portm, t4]
        half = CELL / 2
        ws = G4Box("world", 3 * half[0] + 50, 3 * half[1] + 50, 3 * half[2] + 50)
        wl = G4LogicalVolume(ws, air, "world")
        wp = G4PVPlacement(None, G4ThreeVector(), wl, "world", None, False, WORLD)
        ss = G4Box("scint", *half)
        sl = G4LogicalVolume(ss, scm, "scint")
        sp = G4PVPlacement(None, G4ThreeVector(*half), sl, "scint", wl, False, SCINT)
        self.keep += [ws, wl, wp, ss, sl, sp]
        self.port_lv = []
        for k in (0, 1):
            for nm, mat, cn in ((f"shell{k}", clad, CLAD0 + 2 * k), (f"core{k}", core, CORE0 + 2 * k)):
                ts = G4TessellatedSolid(nm)
                for tri in G[nm] * 10.0:
                    ts.AddFacet(G4TriangularFacet(G4ThreeVector(*tri[0]), G4ThreeVector(*tri[1]), G4ThreeVector(*tri[2]),
                                                  G4FacetVertexType.ABSOLUTE))
                ts.SetSolidClosed(True)
                lv = G4LogicalVolume(ts, mat, nm)
                pv = G4PVPlacement(None, G4ThreeVector(), lv, nm, wl, False, cn)
                self.keep += [ts, lv, pv]
            P = G[f"port{k}_point"] * 10.0; N = G[f"port{k}_normal"]
            bs = G4Box(f"port{k}", SLAB / 2, float(G["core_w"]) * 10.0 / 2, float(G["core_h"]) * 10.0 / 2)
            bl = G4LogicalVolume(bs, portm, f"port{k}")
            rot = G4RotationMatrix(); rot.rotateZ(math.atan2(N[1], N[0]))
            c = P + N * (SLAB / 2)
            bp = G4PVPlacement(G4Transform3D(rot, G4ThreeVector(*c)), bl, f"port{k}", wl, False, PORT0 + k)
            self.keep += [bs, bl, rot, bp]
            self.port_lv.append(bl)
        return wp

    def ConstructSDandField(self):
        sd = PortSD("ports")
        G4SDManager.GetSDMpointer().AddNewDetector(sd)
        for lv in self.port_lv:
            lv.SetSensitiveDetector(sd)
        self.keep.append(sd)


class Physics(G4VModularPhysicsList):
    def __init__(self):
        super().__init__()
        self.SetVerboseLevel(0)
        self.RegisterPhysics(G4OpticalPhysics())


class Gen(G4VUserPrimaryGeneratorAction):
    def __init__(self):
        super().__init__()
        self.gps = G4GeneralParticleSource()

    def GeneratePrimaries(self, event):
        for _ in range(PER_EVENT):
            self.gps.GeneratePrimaryVertex(event)


class Actions(G4VUserActionInitialization):
    def Build(self):
        self.SetUserAction(Gen())


ui = G4UImanager.GetUIpointer()
rm = G4RunManagerFactory.CreateRunManager(G4RunManagerType.Serial)
G4Random.setTheSeed(SEED % 2147483647)
DET = Det()
rm.SetUserInitialization(DET)
rm.SetUserInitialization(Physics())
for proc in ("Cerenkov", "Scintillation", "OpWLS", "OpWLS2", "OpRayleigh", "OpMieHG"):
    ui.ApplyCommand(f"/process/optical/processActivation {proc} false")
rm.SetUserInitialization(Actions())
for cmd in ("/control/verbose 0", "/run/verbose 0", "/event/verbose 0", "/tracking/verbose 0"):
    ui.ApplyCommand(cmd)
rm.Initialize()
b_lo, b_hi = lo * SP, hi * SP
cen, hw = (b_lo + b_hi) / 2, (b_hi - b_lo) / 2
for cmd in ("/gps/particle opticalphoton", "/gps/energy 3.04 eV", "/gps/pos/type Volume", "/gps/pos/shape Para",
            f"/gps/pos/centre {cen[0]} {cen[1]} {cen[2]} mm", f"/gps/pos/halfx {hw[0]} mm", f"/gps/pos/halfy {hw[1]} mm",
            f"/gps/pos/halfz {hw[2]} mm", "/gps/pos/confine scint", "/gps/ang/type iso", "/gps/time 0 ns",
            "/gps/verbose 0"):
    ui.ApplyCommand(cmd)
nev = int(math.ceil(NPH / PER_EVENT))
t0 = time.perf_counter(); cpu0 = time.process_time()
rm.BeamOn(nev)
wall, cpu = time.perf_counter() - t0, time.process_time() - cpu0
n = nev * PER_EVENT
c = np.array(caught, dtype=np.float64).reshape(-1, 3)
np.savez_compressed(OUTF, vox=c[:, 0].astype(np.int32), ch=c[:, 1].astype(np.int8), t=c[:, 2], n=n, wall_s=wall,
                    cpu_s=cpu, lo=lo, hi=hi, seed=SEED)
print(f"{gid} fast n={n} caught0 {np.sum(c[:,1]==0)/n:.5f} caught1 {np.sum(c[:,1]==1)/n:.5f} "
      f"t0 {c[c[:,1]==0,2].mean() if len(c) else float('nan'):.3f} ns  {wall:.1f}s ({n/wall:.0f} ph/s)", flush=True)
